115	// runCLIAudit 在真实进程上运行 audit，返回 stdout、stderr 与退出码。
116	func runCLIAudit(t *testing.T, bin, input, store string) (string, string, int) {
117		t.Helper()
118		cmd := exec.Command(bin, "audit", "--input", input, "--store", store)
119		var stdout, stderr bytes.Buffer
120		cmd.Stdout = &stdout
121		cmd.Stderr = &stderr
122		err := cmd.Run()
123		if err == nil {
124			return stdout.String(), stderr.String(), 0
125		}
126		if exitErr, ok := err.(*exec.ExitError); ok {
127			return stdout.String(), stderr.String(), exitErr.ExitCode()
128		}
129		t.Fatalf("failed to start audit: %v", err)
130		return "", "", 0
131	}
